import { useEffect, useState } from "react";
import api from "../api";
import socket from "../socket";
import LiveMap from "../components/LiveMap";
import CityLocationInput from "../components/CityLocationInput";
import { useCart } from "../context/CartContext";
import "./UserDashboard.css";

export default function UserDashboard() {
  const { cart, loading: cartLoading, error: cartError, loadCart, addToCart, updateItem, removeItem, clearCart } = useCart();
  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [selectedService, setSelectedService] = useState(null);
  const [location, setLocation] = useState("");
  const [coordinates, setCoordinates] = useState(null);
  const [showPayment, setShowPayment] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState("upi");
  const [couponCode, setCouponCode] = useState("");
  const [paymentMethods, setPaymentMethods] = useState({ upiIds: [], qrCodes: [], bankAccounts: [], cardSupported: true, codSupported: true });
  const [addressDetails, setAddressDetails] = useState({});

  const [user, setUser] = useState(null);
  const [search, setSearch] = useState("");
  const [showQR, setShowQR] = useState(false);
  const [showMap, setShowMap] = useState(false);
  
  // Live tracking state
  const [activeBooking, setActiveBooking] = useState(null);
  const [providerLocation, setProviderLocation] = useState(null);
  const [trackingProviderId, setTrackingProviderId] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = JSON.parse(atob(token.split(".")[1]));
        setUser(decoded);
      } catch (err) {
        console.error("Error decoding token:", err);
      }
    }
    loadServices();
    loadBookings();
    loadPaymentMethods();
    socket.on("booking-update", () => {
      loadBookings();
      loadCart();
    });
    socket.on("providerLocationUpdate", (data) => {
      if (data.providerId === trackingProviderId) {
        setProviderLocation({ lat: data.lat, lng: data.lng });
      }
    });
    return () => {
      socket.off("booking-update");
      socket.off("providerLocationUpdate");
    };
  }, [trackingProviderId]);

  const loadServices = async () => {
    try {
      const response = await api.get("/services");
      setServices(response.data);
    } catch (err) {
      console.error("Error loading services:", err);
    }
  };

  const loadBookings = async () => {
    try {
      const response = await api.get("/bookings/my-bookings");
      setBookings(response.data);
    } catch (err) {
      console.error("Error loading bookings:", err);
    }
  };

  const loadPaymentMethods = async () => {
    try {
      const response = await api.get("/admin-payments");
      setPaymentMethods(response.data);
    } catch (err) {
      console.error("Error loading payment methods:", err);
    }
  };

  const handleBooking = (service) => {
    setSelectedService(service);
    setPaymentMethod("upi");
    setShowPayment(true);
  };

  const handleAddToCart = async (service) => {
    try {
      await addToCart({ serviceId: service._id, quantity: 1, price: service.basePrice, description: service.name });
      alert(`${service.name} added to cart`);
    } catch (err) {
      console.error("Error adding to cart:", err);
      alert("Could not add service to cart");
    }
  };

  const [gpsLoading, setGpsLoading] = useState(false);
  const requestCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("Geolocation not supported by this browser");
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;
        const nextCoordinates = { lat, lng };
        setCoordinates(nextCoordinates);

        // No reverse-geocoding library in this project; store readable fallback.
        setLocation(`${lat}, ${lng}`);

        // Also store user location in backend so GeoJSON is correct.
        try {
          await api.put("/auth/update-location", { latitude: lat, longitude: lng, address: "" });
        } catch (e) {
          // Non-blocking: booking can still be created.
          console.warn("Failed to save user location:", e?.response?.data || e.message || e);
        }
      },
      (err) => {
        console.warn("Geolocation error:", err);
        // Allow manual selection / typing fallback
        alert("Location permission denied / unavailable. Please choose location from suggestions.");
      },
      { enableHighAccuracy: true, timeout: 15000 }
    );
  };


  const handlePaymentSuccess = async () => {
    try {
      if (!coordinates) {
        alert("Select / allow location first");
        return;
      }
      const amount = selectedService.suggestedPrice || selectedService.basePrice || 499;
      const payload = {
        serviceId: selectedService._id,
        location,
        coordinates,
        locationDetails: addressDetails,
        paymentMethod,
        amount,
        couponCode: couponCode || undefined,
        tip: 0,
        transactionId: paymentMethod !== "cod" ? `TX-${Date.now()}` : null
      };

      const response = await api.post("/bookings/book", payload);

      if (response.data?.booking) {
        alert("Booking created successfully!");
        setShowPayment(false);
        setSelectedService(null);
        setLocation("");
        setCoordinates(null);
        setShowQR(false);
        setCouponCode("");
        loadBookings();
        loadCart();
      }
    } catch (err) {
      console.error("Error creating booking:", err);
      alert(err.response?.data?.error || "Failed to create booking");
    }
  };

  const cancelBooking = async (bookingId) => {
    try {
      await api.post(`/bookings/status/${bookingId}`, { status: "cancelled" });
      loadBookings();
    } catch (err) {
      console.error("Error cancelling booking:", err);
    }
  };

  const handleTrackBooking = (booking) => {
    setActiveBooking(booking);
    setTrackingProviderId(booking.providerId);
    setShowMap(true);
  };

  const getServiceIcon = (serviceName) => {
    const icons = {
      'Plumber': '🔧',
      'Electrician': '⚡',
      'AC Repair': '❄️',
      'Carpenter': '🪵',
      'House Cleaning': '🧹',
      'Painting': '🎨',
      'Pest Control': '🐛',
      'Gardening': '🌱',
      'Appliance Repair': '🔌',
      'Moving & Packing': '📦'
    };
    return icons[serviceName] || '🔧';
  };

  const filteredServices = services.filter(service => 
    service.name.toLowerCase().includes(search.toLowerCase()) ||
    service.category?.toLowerCase().includes(search.toLowerCase())
  );


  return (
    <div className="dashboard-container">

      {/* Header */}
      <header className="header">
        <h1 className="logo">FASTAID</h1>
        <div className="account-info">
          <span className="welcome-text">Welcome, {user?.name || 'User'} 👋</span>
          <button className="logout-btn" onClick={() => {
            localStorage.removeItem("token");
            window.location.href = "/";
          }}>
            Logout
          </button>
        </div>
      </header>

      {/* Hero Section */}
      <section className="hero">
        <h2>Find Trusted Services Near You</h2>
        <p>
          FASTAID connects you with verified professionals for health, home,
          vehicle, tech and more — quickly and securely.
        </p>

        {/* Trust Badges */}
        <div className="badges">
          <span className="badge">✔ Verified</span>
          <span className="badge">🔒 Secure</span>
          <span className="badge">⚡ Fast Service</span>
        </div>

        {/* Search Box */}
        <div className="search-container">
          <div className="search-box">
            <input
              type="text"
              placeholder="Search services like Plumber, Doctor..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
            <button>Search</button>
          </div>
        </div>

        <button className="category-btn">
          View All Categories
        </button>
      </section>

      {/* Popular Services */}
      <section className="services-section">
        <h3 className="section-title">Popular Services</h3>

        <div className="services-grid">
          {filteredServices.length > 0 ? (
            filteredServices.map((service) => (
              <div key={service._id} className="service-card">
                <div className="service-icon" style={{ fontSize: '40px', marginBottom: '10px' }}>
                  {getServiceIcon(service.name)}
                </div>
                <h4>{service.name}</h4>
                <p className="rating">⭐ {service.rating || '4.5'}</p>
                <p className="service-price">₹ {service.suggestedPrice || service.basePrice || 499}</p>
                <div className="service-actions">
                  <button className="btn btn-secondary" onClick={() => handleAddToCart(service)}>
                    Add to Cart
                  </button>
                  <button className="btn btn-primary" onClick={() => handleBooking(service)}>
                    Book Now
                  </button>
                </div>
              </div>
            ))
          ) : (
            <div className="empty-state" style={{ gridColumn: '1 / -1' }}>
              <div className="empty-state-icon">🔍</div>
              <h3>No services found</h3>
              <p>Try a different search term</p>
            </div>
          )}
        </div>
      </section>

      {/* Cart Section */}
      <section className="cart-section">
        <h3 className="section-title">Your Cart</h3>
        {cartLoading ? (
          <div>Loading cart...</div>
        ) : cart?.items?.length > 0 ? (
          <div className="cart-grid">
            <div className="cart-items">
              {cart.items.map((item) => (
                <div key={item._id} className="cart-card">
                  <div>
                    <h4>{item.serviceName}</h4>
                    <p>Price: ₹{item.price}</p>
                    <p>Qty: {item.quantity}</p>
                    <div className="cart-actions">
                      <button className="btn btn-small" onClick={() => updateItem(item._id, { quantity: item.quantity + 1 })}>
                        +
                      </button>
                      <button className="btn btn-small" onClick={() => updateItem(item._id, { quantity: Math.max(1, item.quantity - 1) })}>
                        -
                      </button>
                      <button className="btn btn-danger btn-small" onClick={() => removeItem(item._id)}>
                        Remove
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
            <div className="cart-summary">
              <p>Tax: ₹{cart.tax || 0}</p>
              <p>Discount: ₹{cart.discount || 0}</p>
              <h4>Total: ₹{cart.total || 0}</h4>
              <button className="btn btn-primary" onClick={() => {
                if (cart.items.length) {
                  const service = services.find((service) => service._id === cart.items[0].serviceId);
                  setSelectedService(service || { name: cart.items[0].serviceName, basePrice: cart.items[0].price });
                  setShowPayment(true);
                }
              }}>
                Checkout First Item
              </button>
              <button className="btn btn-secondary" onClick={clearCart}>
                Clear Cart
              </button>
            </div>
          </div>
        ) : (
          <div className="empty-state">
            <div className="empty-state-icon">🛒</div>
            <h3>Cart is empty</h3>
            <p>Add services to your cart from the list above.</p>
          </div>
        )}
      </section>

      {/* My Bookings Section */}
      <section className="bookings-section">
        <h3 className="bookings-title">My Bookings</h3>

        {bookings.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-icon">📋</div>
            <h3>No bookings yet</h3>
            <p>Book a service to get started!</p>
          </div>
        ) : (
          <div className="services-grid">
            {bookings.map((booking) => (
              <div key={booking._id} className="booking-card">
                <div className="booking-info">
                  <h4>{booking.serviceName}</h4>
                  <p>📍 {booking.location}</p>
                  <p>💰 Payment: {booking.paymentStatus}</p>
                </div>
                <div className="booking-actions">
                  <span className={`status-badge status-${booking.status}`}>
                    {booking.status}
                  </span>
                  {booking.status === "pending" && (
                    <button 
                      onClick={() => cancelBooking(booking._id)}
                      className="cancel-btn"
                    >
                      Cancel
                    </button>
                  )}
                  {booking.providerId && booking.status !== "completed" && booking.status !== "cancelled" && (
                    <button
                      onClick={() => handleTrackBooking(booking)}
                      className="btn btn-secondary btn-small"
                    >
                      Track
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      {showMap && activeBooking && (
        <section className="tracking-section">
          <div className="tracking-card">
            <h3>Live tracking for {activeBooking.serviceName}</h3>
            <p>Status: <strong>{activeBooking.status}</strong></p>
            <LiveMap providerLocation={providerLocation} providerId={trackingProviderId} />
            <button className="btn btn-secondary" onClick={() => setShowMap(false)}>
              Close Tracking
            </button>
          </div>
        </section>
      )}

      {/* Payment Modal */}
      {showPayment && (
        <div className="payment-modal">
          <div className="payment-content">
            <h3>Booking: {selectedService?.name}</h3>
            <p className="modal-subtitle">Pay securely with trusted checkout options</p>
            {!showQR ? (
              <>
                <div className="form-group">
                  <label className="form-label">Location</label>
                  <CityLocationInput
                    value={location}
                    onChange={(val) => {
                      setLocation(typeof val === "string" ? val : val.display || location);
                      if (typeof val === "object") {
                        setAddressDetails(val.details || {});
                      }
                      setCoordinates(null);
                    }}
                    onAddressSelect={(details) => {
                      setAddressDetails(details);
                      setLocation(`${details.street || ""} ${details.city || ""} ${details.state || ""}`.trim());
                    }}
                    coordinates={coordinates}
                    onCoordinatesChange={setCoordinates}
                    placeholder="Enter your city or street"
                    maxSuggestions={8}
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Payment Method</label>
                  <select
                    value={paymentMethod}
                    onChange={(e) => setPaymentMethod(e.target.value)}
                    className="form-select"
                  >
                    {paymentMethods.upiIds.length > 0 && <option value="upi">UPI</option>}
                    {paymentMethods.qrCodes.length > 0 && <option value="qr">QR Code</option>}
                    {paymentMethods.cardSupported && <option value="card">Credit/Debit Card</option>}
                    {paymentMethods.codSupported && <option value="cod">Cash on Delivery</option>}
                    <option value="wallet">Wallet</option>
                  </select>
                </div>

                <div className="payment-sources">
                  {paymentMethods.upiIds?.length > 0 && (
                    <div className="payment-source">
                      <h4>UPI IDs</h4>
                      {paymentMethods.upiIds.map((upi, index) => (
                        <p key={index}>{upi.label || "UPI"}: {upi.value}</p>
                      ))}
                    </div>
                  )}
                  {paymentMethods.bankAccounts?.length > 0 && (
                    <div className="payment-source">
                      <h4>Bank Transfer</h4>
                      {paymentMethods.bankAccounts.map((bank, index) => (
                        <p key={index}>{bank.bankName}: {bank.accountName} / {bank.ifsc}</p>
                      ))}
                    </div>
                  )}
                  {paymentMethods.qrCodes?.length > 0 && (
                    <div className="payment-source">
                      <h4>QR Codes</h4>
                      {paymentMethods.qrCodes.map((qr, index) => (
                        <img key={index} src={qr.url} alt={qr.label} className="payment-qr-image" />
                      ))}
                    </div>
                  )}
                </div>

                <div className="form-group">
                  <label className="form-label">Coupon Code</label>
                  <input
                    type="text"
                    className="form-input"
                    placeholder="Enter coupon code"
                    value={couponCode}
                    onChange={(e) => setCouponCode(e.target.value)}
                  />
                </div>

                <div className="payment-buttons">
                  <button
                    className="pay-btn"
                    onClick={() => {
                      if (paymentMethod === "qr" || paymentMethod === "upi") {
                        requestCurrentLocation();
                        setShowQR(true);
                      } else {
                        handlePaymentSuccess();
                      }
                    }}
                  >
                    Continue
                  </button>
                  <button className="close-btn" onClick={() => {
                    setShowPayment(false);
                    setSelectedService(null);
                    setLocation("");
                    setShowQR(false);
                  }}>
                    Close
                  </button>
                </div>
              </>
            ) : (
              <>
                <div className="payment-qr-list">
                  {paymentMethods.qrCodes?.length ? (
                    paymentMethods.qrCodes.map((qr, index) => (
                      <div key={index} className="payment-qr-card">
                        <img src={qr.url} alt={qr.label} className="payment-qr-image" />
                        <p>{qr.label}</p>
                      </div>
                    ))
                  ) : (
                    <div className="empty-state">
                      <p>No QR codes are configured yet.</p>
                    </div>
                  )}
                </div>
                <p className="qr-help-text">
                  Scan one of the merchant QR codes from your UPI app and confirm the payment.
                </p>
                <div className="payment-buttons">
                  <button className="pay-btn" onClick={handlePaymentSuccess}>
                    ✓ Payment Done
                  </button>
                  <button className="close-btn" onClick={() => setShowQR(false)}>
                    Back
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}

    </div>
  );
}
